style.css:
/* GameJolt Neon Night — gamejolt.com */

/* swap these colors here */
:root {
  --my-bg: #101014;
  --my-card: #1b1b23;
  --my-accent: #39ff88;
  --my-text: #f2f2f5;
}

/* dark background and text */
html,
body {
  background: var(--my-bg) !important;
  color: var(--my-text) !important;
}

/* links */
a {
  color: var(--my-accent) !important;
}

/* images */
img {
  border-radius: 10px !important;
}

/* selection */
::selection {
  background: var(--my-accent) !important;
  color: #101014 !important;
}
